private val Z0=Color(0xFF050912);private val Z1=Color(0xFF0B1422);private val Z2=Color(0xFF111D2D);private val ZT=Color(0xFFF5F7FB);private val ZM=Color(0xFF7F8DA3);private val ZV=Color(0xFF8A45FF);private val ZC=Color(0xFF26D9FF);private val ZG=Color(0xFF21D79B);private val ZR=Color(0xFFFF536F);private val ZY=Color(0xFFFFC857)
