@Composable private fun Market(q:XQuote,on:()->Unit){Card(onClick=on,Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),colors=CardDefaults.cardColors(containerColor=Z1)){Row(Modifier.padding(11.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(38.dp).clip(RoundedCornerShape(12.dp)).background(Brush.linearGradient(listOf(ZV.copy(.2f),ZC.copy(.1f)))),contentAlignment=Alignment.Center){Text(q.s.take(1),color=ZT,fontWeight=FontWeight.Black)};Spacer(Modifier.width(9.dp));Column(Modifier.weight(1f)){Text(q.s.removeSuffix("USDT"),color=ZT,fontWeight=FontWeight.Bold);Text("/ USDT",color=ZM,fontSize=7.sp)};Column(horizontalAlignment=Alignment.End){Text(money(q.p),color=ZT,fontSize=9.sp);Text(pct(q.c),color=if(q.c>=0)ZG else ZR,fontSize=9.sp)}}}}
@Composable private fun Ohlc(c:Candle){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(14.dp),colors=CardDefaults.cardColors(containerColor=Z1)){Row(Modifier.fillMaxWidth().padding(9.dp),horizontalArrangement=Arrangement.SpaceEvenly){Text("O ${money(c.open)}",color=ZT,fontSize=8.sp);Text("H ${money(c.high)}",color=ZG,fontSize=8.sp);Text("L ${money(c.low)}",color=ZR,fontSize=8.sp);Text("C ${money(c.close)}",color=ZT,fontSize=8.sp);Text("V ${compact(c.volume)}",color=ZM,fontSize=8.sp)}}}
@Composable private fun Gauge(score:Int){Canvas(Modifier.size(125.dp)){drawCircle(Color(0xFF1B2B3D),size.minDimension*.34f,center,style=androidx.compose.ui.graphics.drawscope.Stroke(2f));drawCircle(if(score>=70)ZR else ZV,size.minDimension*.18f,center)}}
@Composable private fun Spark(v:List<Double>){Canvas(Modifier.fillMaxWidth().height(30.dp)){if(v.size<2)return@Canvas;val lo=v.minOrNull()?:0.0;val hi=v.maxOrNull()?:1.0;val r=(hi-lo).takeIf{it>0}?:1.0;var last=Offset(0f,size.height);v.forEachIndexed{i,x->val p=Offset(size.width*i/v.lastIndex.toFloat(),size.height-((x-lo)/r*size.height).toFloat());if(i>0)drawLine(ZC,last,p,2f);last=p}}}
private fun money(v:Double)=if(v>=1000)"%,.2f".format(v)else if(v>=1)"%.4f".format(v)else"%.8f".format(v)
private fun pct(v:Double)="%+.2f%%".format(v)
private fun compact(v:Double)=when{v>=1e9->"%.1fB".format(v/1e9);v>=1e6->"%.1fM".format(v/1e6);v>=1e3->"%.1fK".format(v/1e3);else->"%.0f".format(v)}
